@php $mon = now('Asia/Dhaka')->format('Y-m'); $dep = DB::table('employees')->where('active',true)->select(DB::raw("coalesce(department,'No department') d"), DB::raw('count(*) c'), DB::raw("sum(case when coalesce(pay_type,'salary')='commission' then 0 else salary end) s"))->groupBy('d')->orderByDesc('c')->get();
$pr = DB::table('payroll_entries')->where('month',$mon); $tot = (clone $pr)->sum('amount'); $paid = (clone $pr)->where('status','paid')->sum('amount'); $rows = (clone $pr)->count(); @endphp
